// What counts as something a person said, and how it is read out of a Claude Code transcript (JSONL).
//
// The contract (checked against the record shapes real transcripts use, see scripts/fixtures): a record is an original human
// statement only if it is type "user", has a uuid, is not generated by the harness (meta, sidechain, compaction summary,
// transcript-only, tool result, task notification, peer message, command or hook wrapper) and carries text. Everything else is
// ignored. The transcript is streamed, so its size is not a limit. Text is screened for secrets before anything is stored.

import crypto from 'node:crypto';
import fs from 'node:fs';

export const HARNESS = 'claude-code';
const CHUNK = 1 << 20;
const MAX_RECORD_BYTES = 32 * 1024 * 1024;
const ANCHOR_BYTES = 256;
const HARNESS_TEXT = /^\s*<(?:command-|local-command|system-reminder|user-prompt-submit-hook|bash-|task-notification)|^\s*\[Request interrupted|^\s*Caveat: The messages below were generated by the user while running local commands/i;
const GENERATED_FLAGS = ['isMeta', 'isSidechain', 'isCompactSummary', 'isVisibleInTranscriptOnly', 'queueTranscriptOnly', 'toolUseResult', 'sourceToolAssistantUUID', 'sourceToolUseID'];

// The text of an original human record, or null when the record is anything else.
export function humanRecord(entry) {
  if (!entry || entry.type !== 'user' || typeof entry.uuid !== 'string' || !entry.uuid) return null;
  if (GENERATED_FLAGS.some((flag) => entry[flag])) return null;
  if (entry.userType !== undefined && entry.userType !== 'external') return null;
  if (entry.origin !== undefined && entry.origin !== null && entry.origin.kind !== 'human') return null;
  const content = entry.message?.content;
  let text;
  if (typeof content === 'string') text = content;
  else if (Array.isArray(content) && content.length && content.every((b) => b && (b.type === 'text' || b.type === 'image'))) {
    text = content.filter((b) => b.type === 'text' && typeof b.text === 'string').map((b) => b.text).join('\n');
  } else return null;
  text = text.trim();
  if (!text || HARNESS_TEXT.test(text)) return null;
  return { uuid: entry.uuid, ts: typeof entry.timestamp === 'string' ? entry.timestamp : null, cwd: typeof entry.cwd === 'string' ? entry.cwd : null, text };
}

const digest = (buffer) => crypto.createHash('sha256').update(buffer).digest('hex').slice(0, 32);

function anchorOf(fd, end) {
  const length = Math.min(ANCHOR_BYTES, end);
  const buffer = Buffer.alloc(length);
  fs.readSync(fd, buffer, 0, length, end - length);
  return digest(buffer);
}

// Streams complete lines from `from` (0 unless the bytes just before it are still the bytes that were captured). Returns the
// human records, the offset after the last complete line and the anchor that proves it. A partial last line is left for next time.
export function scanTranscript(file, { from = 0, anchor = '' } = {}) {
  const fd = fs.openSync(file, 'r');
  try {
    const size = fs.fstatSync(fd).size;
    if (!fs.fstatSync(fd).isFile()) throw new Error('transcript_unreadable');
    if (from > size || (from > 0 && anchorOf(fd, from) !== anchor)) from = 0; // not the file we saw: read it all again (records are unique by uuid)
    const records = [];
    let oversize = 0;
    let carry = Buffer.alloc(0);
    let skipping = false;
    let lineStart = from;
    let position = from;
    let end = from;
    const buffer = Buffer.alloc(CHUNK);
    for (;;) {
      const read = fs.readSync(fd, buffer, 0, CHUNK, position);
      if (!read) break;
      let begin = 0;
      for (let i = 0; i < read; i += 1) {
        if (buffer[i] !== 10) continue;
        if (!skipping) {
          const line = Buffer.concat([carry, buffer.subarray(begin, i)]);
          const record = parseLine(line);
          if (record) records.push({ ...record, seq: lineStart });
        } else oversize += 1;
        carry = Buffer.alloc(0);
        skipping = false;
        begin = i + 1;
        lineStart = position + i + 1;
        end = lineStart;
      }
      if (!skipping) {
        carry = Buffer.concat([carry, buffer.subarray(begin, read)]);
        if (carry.length > MAX_RECORD_BYTES) { carry = Buffer.alloc(0); skipping = true; }
      }
      position += read;
    }
    return { records, end, anchor: end > 0 ? anchorOf(fd, end) : '', oversize };
  } finally {
    fs.closeSync(fd);
  }
}

function parseLine(line) {
  try {
    return humanRecord(JSON.parse(line.toString('utf8')));
  } catch {
    return null;
  }
}

// -- secrets ------------------------------------------------------------------------------------------------------------

// A message that names a credential, or looks like one, is never stored. The VALUE it names is remembered (as a salted hash,
// never in the clear) so that a later message repeating it, in any window, session or after a restart, is dropped too.
export const SECRET = /pass(?:word|wd|phrase|code)|\bpwd\b|\bpin\b|secret|credential|api[ _-]?key|(?:access|refresh|auth|bearer|session)[ _-]?token|\btoken\b|private[ _-]?key|recovery[ _-]?code|\b(?:ssn|iban|cvv|passport)\b|social security|credit[ _-]?card|\bsk-[A-Za-z0-9_-]{12,}|\b[A-Za-z0-9+/_-]{28,}\b|\b(?:\d[ -]?){13,19}\b/i;
const LABEL_VALUE = /(?:pass(?:word|wd|phrase|code)|pwd|\bpin|secret|token|api[ _-]?key|private[ _-]?key|credential|recovery[ _-]?code|cvv|passport|ssn|iban)s?(\s*(?:is|are|was|=|:|->|-)\s*|\s+)["'`]?([^\s"'`]{4,})/gi;
const KEYLIKE = /\bsk-[A-Za-z0-9_-]{12,}|\b[A-Za-z0-9+/_-]{28,}\b|\b(?:\d[ -]?){13,19}\b/g;
const EDGE = /^[\s.,;:!?()[\]{}"'`<>]+|[\s.,;:!?()[\]{}"'`<>]+$/g;

export const labelled = (text) => SECRET.test(text);
const clean = (token) => token.replace(EDGE, '').normalize('NFKC').toLowerCase();

// Tokens of a text in the form used for matching secrets (whole whitespace-separated words, with and without edge punctuation).
export function tokensOf(text) {
  const out = new Set();
  for (const raw of text.split(/\s+/)) {
    const bare = clean(raw);
    if (bare.length >= 4) out.add(bare);
    const loose = raw.normalize('NFKC').toLowerCase();
    if (loose.length >= 4) out.add(loose);
  }
  return out;
}

// The credential values a labelled text names: the word after "password is" (or a value that itself looks like a credential:
// it has a digit or a symbol), plus anything that looks like a key or card number.
export function secretValues(text) {
  const values = new Set();
  for (const m of text.matchAll(LABEL_VALUE)) {
    const value = m[2];
    if (/\b(?:is|are|was)\b|[=:]|->/.test(m[1]) || /[0-9!@#$%^&*_+=/-]/.test(value)) {
      const bare = clean(value);
      if (bare.length >= 4) values.add(bare);
      values.add(value.normalize('NFKC').toLowerCase());
    }
  }
  for (const m of text.matchAll(KEYLIKE)) values.add(m[0].normalize('NFKC').toLowerCase());
  return values;
}
